1	import { useState } from 'react';
2	import { Users, Link2, Phone, QrCode, Copy, Check, Clock, Star, Briefcase, X, Loader2, UserPlus } from 'lucide-react';
3	import { useCompanyTeam } from '../../hooks/useTeamConnections';
4	import { TeamConnectionService } from '../../services/teamConnectionService';
5	import { useAuth } from '../../contexts/AuthContext';
6	import type { TeamMember, TeamConnection } from '../../types';
7	
8	// ---------------------------------------------------------------------------
9	// Subcomponent: card de membro da equipe
10	// ---------------------------------------------------------------------------
11	
12	interface MemberCardProps {
13	  member: TeamMember;
14	}
15	
16	function MemberCard({ member }: MemberCardProps) {
17	  const { worker } = member;
18	  const avatarUrl = worker.avatar_url ?? worker.photo_url ?? null;
19	
20	  return (
21	    <div className="bg-white border-2 border-black rounded-2xl p-5 flex items-start gap-4 hover:shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] hover:-translate-y-0.5 transition-all">
22	      {/* Avatar */}
23	      <div className="w-14 h-14 rounded-xl border-2 border-black overflow-hidden bg-gray-100 flex-shrink-0">
24	        {avatarUrl ? (
25	          <img src={avatarUrl} alt={worker.full_name} className="w-full h-full object-cover" />
26	        ) : (
27	          <div className="w-full h-full flex items-center justify-center bg-black text-white font-black text-xl">
28	            {worker.full_name?.[0]?.toUpperCase() ?? '?'}
29	          </div>
30	        )}
31	      </div>
32	
33	      {/* Info */}
34	      <div className="flex-1 min-w-0">
35	        <h3 className="font-black uppercase text-base truncate">{worker.full_name}</h3>
36	        {worker.primary_role && (
37	          <p className="text-sm font-bold text-gray-500 uppercase truncate">{worker.primary_role}</p>
38	        )}
39	        <div className="flex flex-wrap gap-2 mt-2">
40	          {typeof worker.rating_average === 'number' && (
41	            <span className="flex items-center gap-1 text-xs font-bold bg-yellow-50 text-yellow-700 px-2 py-1 rounded-xl border border-yellow-200">
42	              <Star size={12} fill="currentColor" /> {worker.rating_average.toFixed(1)}
43	            </span>
44	          )}
45	          {typeof worker.completed_jobs_count === 'number' && (
46	            <span className="flex items-center gap-1 text-xs font-bold bg-gray-100 text-gray-600 px-2 py-1 rounded-xl">
47	              <Briefcase size={12} /> {worker.completed_jobs_count} jobs
48	            </span>
49	          )}
50	          {worker.city && (
51	            <span className="text-xs font-bold bg-blue-50 text-blue-700 px-2 py-1 rounded-xl">
52	              {worker.city}
53	            </span>
54	          )}
55	        </div>
56	      </div>
57	
58	      {/* Status badge */}
59	      <span className="flex-shrink-0 bg-primary-light text-primary text-xs font-black uppercase px-2 py-1 rounded-xl border border-green-200">
60	        Equipe
61	      </span>
62	    </div>
63	  );
64	}
65	
66	// ---------------------------------------------------------------------------
67	// Subcomponent: card de conexão pendente
68	// ---------------------------------------------------------------------------
69	
70	interface PendingCardProps {
71	  connection: TeamConnection;
72	}
73	
74	function PendingCard({ connection }: PendingCardProps) {
75	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
76	  const workerData = (connection as any).worker as { full_name?: string; avatar_url?: string; primary_role?: string } | undefined;
77	  const name = workerData?.full_name ?? 'Freela';
78	
79	  return (
80	    <div className="bg-gray-50 border-2 border-dashed border-gray-300 rounded-2xl p-4 flex items-center gap-3">
81	      <div className="w-10 h-10 rounded-xl bg-gray-200 border-2 border-gray-300 flex items-center justify-center font-black text-gray-500">
82	        {name[0]?.toUpperCase() ?? '?'}
83	      </div>
84	      <div className="flex-1 min-w-0">
85	        <p className="font-black uppercase text-sm truncate">{name}</p>
86	        {workerData?.primary_role && (
87	          <p className="text-xs font-bold text-gray-400 uppercase">{workerData.primary_role}</p>
88	        )}
89	      </div>
90	      <div className="flex items-center gap-1 text-xs font-bold text-yellow-700 bg-yellow-50 px-2 py-1 rounded-xl border border-yellow-200">
91	        <Clock size={12} /> Aguardando
92	      </div>
93	    </div>
94	  );
95	}
96	
97	// ---------------------------------------------------------------------------
98	// Subcomponent: modal "Adicionar freela"
99	// ---------------------------------------------------------------------------
100	
101	type AddMethod = 'link' | 'phone';
102	
103	interface AddWorkerModalProps {
104	  companyId: string;
105	  onClose: () => void;
106	  onAdded: () => void;
107	  addWorker: (workerId: string, source: 'qr' | 'link' | 'phone') => Promise<boolean>;
108	}
109	
110	function AddWorkerModal({ companyId, onClose, onAdded, addWorker }: AddWorkerModalProps) {
111	  const [method, setMethod] = useState<AddMethod>('link');
112	  const [phone, setPhone] = useState('');
113	  const [workerId, setWorkerId] = useState('');
114	  const [loading, setLoading] = useState(false);
115	  const [copied, setCopied] = useState(false);
116	
117	  const { url: inviteUrl } = TeamConnectionService.generateInviteToken(companyId);
118	
119	  const handleCopyLink = async () => {
120	    try {
121	      await navigator.clipboard.writeText(inviteUrl);
122	      setCopied(true);
123	      setTimeout(() => setCopied(false), 2500);
124	    } catch {
125	      // fallback: selecionar o texto
126	    }
127	  };
128	
129	  const handlePhoneSubmit = async () => {
130	    if (!workerId.trim()) return;
131	    setLoading(true);
132	    const ok = await addWorker(workerId.trim(), 'phone');
133	    setLoading(false);
134	    if (ok) {
135	      onAdded();
136	      onClose();
137	    }
138	  };
139	
140	  return (
141	    <div
142	      className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200"
143	      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
144	    >
145	      <div className="bg-white rounded-2xl border-2 border-black shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] w-full max-w-md p-6">
146	        {/* Header */}
147	        <div className="flex items-center justify-between mb-6">
148	          <h2 className="text-2xl font-black uppercase tracking-tight">Adicionar Freela</h2>
149	          <button onClick={onClose} aria-label="Fechar" className="p-2 hover:bg-gray-100 rounded-xl transition-colors">
150	            <X size={20} />
151	          </button>
152	        </div>
153	
154	        {/* Tabs */}
155	        <div className="flex gap-2 mb-6 border-b-2 border-gray-200 pb-1">
156	          {([
157	            { id: 'link' as AddMethod, icon: Link2, label: 'Link' },
158	            { id: 'phone' as AddMethod, icon: Phone, label: 'Telefone' },
159	          ] as const).map((tab) => (
160	            <button
161	              key={tab.id}
162	              onClick={() => setMethod(tab.id)}
163	              className={`flex items-center gap-2 px-4 py-2 rounded-t-xl font-black uppercase text-sm transition-all ${
164	                method === tab.id
165	                  ? 'bg-black text-white translate-y-[2px]'
166	                  : 'text-gray-400 hover:text-black hover:bg-gray-100'
167	              }`}
168	            >
169	              <tab.icon size={16} /> {tab.label}
170	            </button>
171	          ))}
172	          {/* QR: destaque como "em breve" */}
173	          <button
174	            disabled
175	            className="flex items-center gap-2 px-4 py-2 rounded-t-xl font-black uppercase text-sm text-gray-300 cursor-not-allowed"
176	            title="Scanner QR disponível na v1.1"
177	          >
178	            <QrCode size={16} /> QR (v1.1)
179	          </button>
180	        </div>
181	
182	        {/* Conteúdo por método */}
183	        {method === 'link' && (
184	          <div className="space-y-4">
185	            <p className="text-sm font-bold text-gray-600">
186	              Compartilhe este link com o freela. Ele abrirá o Worki e aceitará o convite de entrada na sua equipe.
187	            </p>
188	            <div className="bg-gray-50 border-2 border-black rounded-xl p-4 flex items-center gap-3 font-mono text-xs break-all text-gray-700">
189	              <span className="flex-1">{inviteUrl}</span>
190	            </div>
191	            <button
192	              onClick={handleCopyLink}
193	              className="w-full bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase flex items-center justify-center gap-2 transition-colors"
194	            >
195	              {copied ? <Check size={18} /> : <Copy size={18} />}
196	              {copied ? 'Copiado!' : 'Copiar Link'}
197	            </button>
198	            <p className="text-xs text-gray-400 text-center">
199	              O freela aparecerá em "Aguardando" até aceitar o convite.
200	            </p>
201	          </div>
202	        )}
203	
204	        {method === 'phone' && (
205	          <div className="space-y-4">
206	            <p className="text-sm font-bold text-gray-600">
207	              Digite o <span className="font-black">ID do worker</span> (Worki ID) para adicionar diretamente.
208	              Busca por telefone disponível na v1.1.
209	            </p>
210	            <div className="space-y-2">
211	              <label htmlFor="phone-input" className="text-xs font-bold uppercase tracking-wide">
212	                Worki ID do freela
213	              </label>
214	              <input
215	                id="phone-input"
216	                type="text"
217	                value={phone}
218	                onChange={(e) => { setPhone(e.target.value); setWorkerId(e.target.value); }}
219	                placeholder="Cole o ID do freela aqui"
220	                className="w-full border-2 border-black rounded-xl px-4 py-3 font-bold focus:ring-2 focus:ring-primary outline-none"
221	              />
222	            </div>
223	            <button
224	              onClick={handlePhoneSubmit}
225	              disabled={loading || !workerId.trim()}
226	              className="w-full bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase flex items-center justify-center gap-2 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
227	            >
228	              {loading ? <Loader2 className="animate-spin" size={18} /> : <UserPlus size={18} />}
229	              {loading ? 'Enviando...' : 'Enviar Convite'}
230	            </button>
231	            <p className="text-xs text-gray-400">
232	              Busca por CPF/telefone disponível na v1.1. Por enquanto, peça o Worki ID ao freela.
233	            </p>
234	          </div>
235	        )}
236	      </div>
237	    </div>
238	  );
239	}
240	
241	// ---------------------------------------------------------------------------
242	// Página principal: CompanyTeam
243	// ---------------------------------------------------------------------------
244	
245	export default function CompanyTeam() {
246	  const { teamMembers, pendingConnections, loading, addWorker, refresh } = useCompanyTeam();
247	  const { user } = useAuth();
248	  const [showAddModal, setShowAddModal] = useState(false);
249	
250	  // Para gerar o token de convite precisamos do company_id (owner_id = user.id → company.id
251	  // é resolvido no service; para o modal passamos o user.id e o service busca o company_id real).
252	  // Aqui usamos user.id como proxy para generateInviteToken — o service usa company_id via query.
253	  const companyIdProxy = user?.id ?? '';
254	
255	  if (loading) {
256	    return (
257	      <div className="max-w-4xl mx-auto space-y-6 animate-pulse pb-20">
258	        <div className="h-10 bg-gray-200 rounded-xl w-48" />
259	        <div className="h-12 bg-gray-200 rounded-xl w-40" />
260	        <div className="space-y-4">
261	          {[...Array(3)].map((_, i) => (
262	            <div key={i} className="h-24 bg-gray-200 rounded-2xl" />
263	          ))}
264	        </div>
265	      </div>
266	    );
267	  }
268	
269	  return (
270	    <div className="max-w-4xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-4 duration-400">
271	      {/* Header */}
272	      <div className="flex items-start justify-between mb-8 gap-4 flex-wrap">
273	        <div>
274	          <h1 className="text-4xl font-black uppercase tracking-tighter">Minha Equipe</h1>
275	          <p className="text-gray-500 font-bold mt-1">
276	            {teamMembers.length} freela{teamMembers.length !== 1 ? 's' : ''} na equipe
277	            {pendingConnections.length > 0 && (
278	              <span className="ml-2 text-yellow-600">· {pendingConnections.length} aguardando aceite</span>
279	            )}
280	          </p>
281	        </div>
282	        <button
283	          onClick={() => setShowAddModal(true)}
284	          className="bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase flex items-center gap-2 transition-colors shadow-[4px_4px_0px_0px_rgba(0,166,81,1)]"
285	        >
286	          <UserPlus size={20} /> Adicionar Freela
287	        </button>
288	      </div>
289	
290	      {/* Equipe aceita */}
291	      {teamMembers.length > 0 && (
292	        <section className="mb-8">
293	          <h2 className="text-xl font-black uppercase mb-4 flex items-center gap-2">
294	            <Users size={20} /> Equipe Ativa
295	          </h2>
296	          <div className="grid grid-cols-1 gap-4">
297	            {teamMembers.map((member) => (
298	              <MemberCard key={member.connection.id} member={member} />
299	            ))}
300	          </div>
301	        </section>
302	      )}
303	
304	      {/* Convites pendentes */}
305	      {pendingConnections.length > 0 && (
306	        <section className="mb-8">
307	          <h2 className="text-xl font-black uppercase mb-4 flex items-center gap-2 text-yellow-700">
308	            <Clock size={20} /> Aguardando Aceite
309	          </h2>
310	          <div className="space-y-3">
311	            {pendingConnections.map((conn) => (
312	              <PendingCard key={conn.id} connection={conn} />
313	            ))}
314	          </div>
315	        </section>
316	      )}
317	
318	      {/* Empty state */}
319	      {teamMembers.length === 0 && pendingConnections.length === 0 && (
320	        <div className="text-center py-20 border-2 border-dashed border-gray-200 rounded-2xl bg-gray-50">
321	          <Users size={48} className="mx-auto mb-4 text-gray-300" />
322	          <h3 className="text-xl font-black uppercase mb-2">Equipe vazia</h3>
323	          <p className="text-gray-500 font-bold mb-6 max-w-sm mx-auto">
324	            Adicione freelas via link de convite, Worki ID ou QR (em breve). Eles aparecerão aqui após aceitarem.
325	          </p>
326	          <button
327	            onClick={() => setShowAddModal(true)}
328	            className="bg-black hover:bg-primary text-white px-8 py-3 rounded-xl font-black uppercase inline-flex items-center gap-2 transition-colors"
329	          >
330	            <UserPlus size={20} /> Adicionar Primeiro Freela
331	          </button>
332	        </div>
333	      )}
334	
335	      {/* Modal Adicionar */}
336	      {showAddModal && (
337	        <AddWorkerModal
338	          companyId={companyIdProxy}
339	          onClose={() => setShowAddModal(false)}
340	          onAdded={refresh}
341	          addWorker={addWorker}
342	        />
343	      )}
344	    </div>
345	  );
346	}
