1	import { BrowserRouter, Routes, Route, useNavigate } from 'react-router-dom';
2	import { useEffect, useState } from 'react';
3	import { supabase } from './lib/supabase';
4	import ProtectedRoute from './components/ProtectedRoute';
5	import ErrorBoundary from './components/ErrorBoundary';
6	import { ToastProvider } from './contexts/ToastContext';
7	import { AuthProvider } from './contexts/AuthContext';
8	import { NotificationProvider } from './contexts/NotificationContext';
9	
10	import { Suspense, lazy } from 'react';
11	
12	// Lazy Load Layouts
13	const MainLayout = lazy(() => import('./layouts/MainLayout'));
14	const CompanyLayout = lazy(() => import('./layouts/CompanyLayout'));
15	
16	// Lazy Load Pages
17	const Dashboard = lazy(() => import('./pages/Dashboard'));
18	const Login = lazy(() => import('./pages/Login'));
19	const Onboarding = lazy(() => import('./pages/Onboarding'));
20	const CompanyOnboarding = lazy(() => import('./pages/company/CompanyOnboarding'));
21	const WorkerOnboarding = lazy(() => import('./pages/worker/WorkerOnboarding'));
22	const WorkerDashboard = lazy(() => import('./pages/worker/WorkerDashboard'));
23	const CompanyDashboard = lazy(() => import('./pages/company/CompanyDashboard'));
24	const Jobs = lazy(() => import('./pages/Jobs'));
25	const Messages = lazy(() => import('./pages/Messages'));
26	const Profile = lazy(() => import('./pages/Profile'));
27	const Analytics = lazy(() => import('./pages/Analytics'));
28	const MyJobs = lazy(() => import('./pages/MyJobs'));
29	const Wallet = lazy(() => import('./pages/Wallet'));
30	
31	// Company Pages
32	const CompanyCreateJob = lazy(() => import('./pages/company/CompanyCreateJob'));
33	const CompanyJobs = lazy(() => import('./pages/company/CompanyJobs'));
34	const CompanyProfile = lazy(() => import('./pages/company/CompanyProfile'));
35	const CompanyAnalytics = lazy(() => import('./pages/company/CompanyAnalytics'));
36	const CompanyJobDetails = lazy(() => import('./pages/company/CompanyJobDetails'));
37	const CompanyJobCandidates = lazy(() => import('./pages/company/CompanyJobCandidates'));
38	const CompanyMessages = lazy(() => import('./pages/company/CompanyMessages'));
39	const CompanyWallet = lazy(() => import('./pages/company/CompanyWallet'));
40	const CompanyTeam = lazy(() => import('./pages/company/CompanyTeam'));
41	const WorkerPublicProfile = lazy(() => import('./pages/company/WorkerPublicProfile'));
42	const NotFound = lazy(() => import('./pages/NotFound'));
43	const Terms = lazy(() => import('./pages/Terms'));
44	const Privacy = lazy(() => import('./pages/Privacy'));
45	const ForgotPassword = lazy(() => import('./pages/ForgotPassword'));
46	const ResetPassword = lazy(() => import('./pages/ResetPassword'));
47	const Admin = lazy(() => import('./pages/Admin'));
48	const Help = lazy(() => import('./pages/Help'));
49	const Notifications = lazy(() => import('./pages/Notifications'));
50	const LandingPage = lazy(() => import('./pages/LandingPage'));
51	
52	// Loading Component - Skeleton placeholder
53	const PageLoader = () => (
54	  <div className="h-screen w-full bg-[#F4F4F0] animate-pulse">
55	    <div className="flex flex-col md:flex-row max-w-7xl mx-auto min-h-screen">
56	      <div className="hidden md:block w-64 p-6 space-y-4">
57	        <div className="h-8 w-24 bg-gray-200 rounded-lg" />
58	        <div className="space-y-3 mt-8">
59	          {[...Array(5)].map((_, i) => <div key={i} className="h-10 bg-gray-200 rounded-xl" />)}
60	        </div>
61	      </div>
62	      <main className="flex-1 p-4 md:p-8 space-y-6">
63	        <div className="h-10 w-48 bg-gray-200 rounded-xl" />
64	        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
65	          {[...Array(3)].map((_, i) => <div key={i} className="h-28 bg-gray-200 rounded-xl" />)}
66	        </div>
67	        <div className="space-y-3">
68	          {[...Array(4)].map((_, i) => <div key={i} className="h-20 bg-gray-200 rounded-xl" />)}
69	        </div>
70	      </main>
71	    </div>
72	  </div>
73	);
74	
75	// Componente para redirecionar usuários logados da raiz
76	function HomeRedirect() {
77	  const navigate = useNavigate();
78	  const [checking, setChecking] = useState(true);
79	
80	  useEffect(() => {
81	    supabase.auth.getUser().then(({ data: { user } }) => {
82	      if (user) {
83	        const userType = user.user_metadata?.user_type;
84	        if (userType === 'hire') {
85	          navigate('/company/dashboard');
86	        } else {
87	          navigate('/dashboard');
88	        }
89	      }
90	      setChecking(false);
91	    });
92	  }, [navigate]);
93	
94	  if (checking) return <div className="h-screen flex items-center justify-center bg-[#F4F4F0] animate-pulse"><div className="h-12 w-32 bg-gray-200 rounded-xl" /></div>;
95	
96	  return <Onboarding />;
97	}
98	
99	import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
100	
101	// Create a client
102	const queryClient = new QueryClient({
103	  defaultOptions: {
104	    queries: {
105	      staleTime: 1000 * 60 * 5, // 5 minutes
106	      gcTime: 1000 * 60 * 30, // 30 minutes
107	      refetchOnWindowFocus: false,
108	    },
109	  },
110	});
111	
112	function App() {
113	  return (
114	    <ErrorBoundary>
115	    <QueryClientProvider client={queryClient}>
116	      <AuthProvider>
117	        <NotificationProvider>
118	          <ToastProvider>
119	            <BrowserRouter>
120	              <Suspense fallback={<PageLoader />}>
121	                <Routes>
122	                  {/* Public Routes */}
123	                  <Route path="/" element={<HomeRedirect />} />
124	                  <Route path="/login" element={<Login />} />
125	                  <Route path="/termos" element={<Terms />} />
126	                  <Route path="/privacidade" element={<Privacy />} />
127	                  <Route path="/esqueci-senha" element={<ForgotPassword />} />
128	                  <Route path="/redefinir-senha" element={<ResetPassword />} />
129	                  <Route path="/ajuda" element={<Help />} />
130	                  <Route path="/sobre" element={<LandingPage />} />
131	
132	                  {/* Protected Routes */}
133	                  <Route element={<ProtectedRoute />}>
134	
135	                    {/* Admin Route - protected, Admin.tsx checks email authorization */}
136	                    <Route path="/admin" element={<Admin />} />
137	
138	                    {/* Onboarding Routes - still protected as they need user session but not full layout yet if incomplete */}
139	                    <Route path="/company/onboarding" element={<CompanyOnboarding />} />
140	                    <Route path="/worker/onboarding" element={<WorkerOnboarding />} />
141	
142	                    {/* Worker Layout Routes */}
143	                    <Route path="/" element={<MainLayout />}>
144	                      <Route path="dashboard" element={<Dashboard />} />
145	                      <Route path="jobs" element={<Jobs />} />
146	                      <Route path="my-jobs" element={<MyJobs />} />
147	                      <Route path="analytics" element={<Analytics />} />
148	                      <Route path="wallet" element={<Wallet />} />
149	                      <Route path="profile" element={<Profile />} />
150	                      <Route path="messages" element={<Messages />} />
151	                      <Route path="notifications" element={<Notifications />} />
152	                      <Route path="worker/dashboard" element={<WorkerDashboard />} />
153	                    </Route>
154	
155	                    {/* Company Layout Routes */}
156	                    <Route path="/company" element={<CompanyLayout />}>
157	                      <Route path="dashboard" element={<CompanyDashboard />} />
158	                      <Route path="create" element={<CompanyCreateJob />} />
159	                      <Route path="jobs" element={<CompanyJobs />} />
160	                      <Route path="jobs/:id" element={<CompanyJobDetails />} />
161	                      <Route path="jobs/:id/edit" element={<CompanyCreateJob />} />
162	                      <Route path="jobs/:id/candidates" element={<CompanyJobCandidates />} />
163	                      <Route path="worker/:id" element={<WorkerPublicProfile />} />
164	                      <Route path="profile" element={<CompanyProfile />} />
165	                      <Route path="messages" element={<CompanyMessages />} />
166	                      <Route path="wallet" element={<CompanyWallet />} />
167	                      <Route path="analytics" element={<CompanyAnalytics />} />
168	                      <Route path="team" element={<CompanyTeam />} />
169	                      <Route path="notifications" element={<Notifications />} />
170	                    </Route>
171	
172	                  </Route>
173	                  <Route path="*" element={<NotFound />} />
174	                </Routes>
175	              </Suspense>
176	            </BrowserRouter>
177	          </ToastProvider>
178	        </NotificationProvider>
179	      </AuthProvider>
