1	/**
2	 * useShiftInvites — hook de UI para convites de turno push (Slice 1, R5/R7/R8).
3	 *
4	 * Dois modos de uso:
5	 *   - useWorkerInvites: lista convites pendentes do worker + actions de resposta.
6	 *   - useCompanyInvites: lista convites enviados por job + action de convidar.
7	 *
8	 * Padrão do projeto: useState + useEffect + supabase direto (Art. 5 — sem React Query).
9	 */
10	
11	import { useState, useEffect, useCallback } from 'react';
12	import { useNavigate } from 'react-router-dom';
13	import { supabase } from '../lib/supabase';
14	import { ShiftInviteService } from '../services/shiftInviteService';
15	import { useToast } from '../contexts/ToastContext';
16	import type { Application, InvitationResponse } from '../types';
17	
18	// ---------------------------------------------------------------------------
19	// Hook para WORKER — aba "Convites"
20	// ---------------------------------------------------------------------------
21	
22	export interface UseWorkerInvitesResult {
23	  /** Convites de turno pendentes (status='invited'). */
24	  pendingInvites: Application[];
25	  loading: boolean;
26	  /** ID do convite sendo processado (para loading state no botão). */
27	  respondingId: string | null;
28	  /** Aceitar ou recusar um convite. */
29	  respond: (applicationId: string, response: InvitationResponse) => Promise<boolean>;
30	  /** Recarregar convites. */
31	  refresh: () => void;
32	}
33	
34	export function useWorkerInvites(): UseWorkerInvitesResult {
35	  const [pendingInvites, setPendingInvites] = useState<Application[]>([]);
36	  const [loading, setLoading] = useState(true);
37	  const [respondingId, setRespondingId] = useState<string | null>(null);
38	  const navigate = useNavigate();
39	  const { addToast } = useToast();
40	
41	  const load = useCallback(async () => {
42	    const {
43	      data: { user },
44	    } = await supabase.auth.getUser();
45	    if (!user) {
46	      navigate('/login');
47	      return;
48	    }
49	
50	    setLoading(true);
51	    const invites = await ShiftInviteService.listPendingInvites();
52	    setPendingInvites(invites);
53	    setLoading(false);
54	  }, [navigate]);
55	
56	  useEffect(() => {
57	    let active = true;
58	    void (async () => {
59	      const {
60	        data: { user },
61	      } = await supabase.auth.getUser();
62	      if (!user) {
63	        navigate('/login');
64	        return;
65	      }
66	
67	      setLoading(true);
68	      const invites = await ShiftInviteService.listPendingInvites();
69	      if (!active) return;
70	      setPendingInvites(invites);
71	      setLoading(false);
72	    })();
73	    return () => {
74	      active = false;
75	    };
76	  }, [navigate]);
77	
78	  const respond = useCallback(
79	    async (applicationId: string, response: InvitationResponse): Promise<boolean> => {
80	      setRespondingId(applicationId);
81	      const result = await ShiftInviteService.respondToInvite(applicationId, response);
82	      setRespondingId(null);
83	
84	      if (result.error) {
85	        addToast(result.error, 'error');
86	        return false;
87	      }
88	
89	      if (response === 'accepted') {
90	        addToast('Turno confirmado! Bom trabalho.', 'success');
91	      } else {
92	        addToast('Convite recusado.', 'info');
93	      }
94	
95	      // Recarregar lista (o convite respondido some dos pendentes)
96	      load();
97	      return true;
98	    },
99	    [addToast, load],
100	  );
101	
102	  return { pendingInvites, loading, respondingId, respond, refresh: load };
103	}
104	
105	// ---------------------------------------------------------------------------
106	// Hook para EMPRESA — gerenciar convites por job
107	// ---------------------------------------------------------------------------
108	
109	export interface UseCompanyInvitesResult {
110	  /** Convites enviados para o job. */
111	  invites: Application[];
112	  loading: boolean;
113	  /** ID do worker sendo convidado (para loading state). */
114	  invitingWorkerId: string | null;
115	  /** Convidar worker da equipe para o turno. */
116	  invite: (workerId: string, opts?: { expiresInHours?: number; message?: string }) => Promise<boolean>;
117	  /** Recarregar convites do job. */
118	  refresh: () => void;
119	}
120	
121	export function useCompanyInvites(jobId: string): UseCompanyInvitesResult {
122	  const [invites, setInvites] = useState<Application[]>([]);
123	  const [loading, setLoading] = useState(true);
124	  const [invitingWorkerId, setInvitingWorkerId] = useState<string | null>(null);
125	  const navigate = useNavigate();
126	  const { addToast } = useToast();
127	
128	  const load = useCallback(async () => {
129	    const {
130	      data: { user },
131	    } = await supabase.auth.getUser();
132	    if (!user) {
133	      navigate('/login');
134	      return;
135	    }
136	
137	    setLoading(true);
138	    const list = await ShiftInviteService.listInvitesByJob(jobId);
139	    setInvites(list);
140	    setLoading(false);
141	  }, [jobId, navigate]);
142	
143	  useEffect(() => {
144	    let active = true;
145	    void (async () => {
146	      const {
147	        data: { user },
148	      } = await supabase.auth.getUser();
149	      if (!user) {
150	        navigate('/login');
151	        return;
152	      }
153	
154	      setLoading(true);
155	      const list = await ShiftInviteService.listInvitesByJob(jobId);
156	      if (!active) return;
157	      setInvites(list);
158	      setLoading(false);
159	    })();
160	    return () => {
161	      active = false;
162	    };
163	  }, [jobId, navigate]);
164	
165	  const invite = useCallback(
166	    async (
167	      workerId: string,
168	      opts: { expiresInHours?: number; message?: string } = {},
169	    ): Promise<boolean> => {
170	      setInvitingWorkerId(workerId);
171	      const result = await ShiftInviteService.inviteWorkerToShift(jobId, workerId, opts);
172	      setInvitingWorkerId(null);
173	
174	      if (result.alreadyInvited) {
175	        addToast('Este freela já foi convidado para este turno.', 'info');
176	        return true;
177	      }
178	      if (result.error) {
179	        addToast(result.error, 'error');
180	        return false;
181	      }
182	
183	      addToast('Convite enviado com sucesso!', 'success');
184	      load();
185	      return true;
186	    },
187	    [jobId, addToast, load],
188	  );
189	
190	  return { invites, loading, invitingWorkerId, invite, refresh: load };
191	}
