1	import { useEffect, useState } from 'react';
2	import { Navigate, Outlet, useLocation } from 'react-router-dom';
3	import { supabase } from '../lib/supabase';
4	import { logError } from '../lib/logger';
5	import { useToast } from '../contexts/ToastContext';
6	import { Loader2 } from 'lucide-react';
7	import TosGateModal from './TosGateModal';
8	
9	export default function ProtectedRoute() {
10	    const [loading, setLoading] = useState(true);
11	    const [user, setUser] = useState<{ id: string; user_metadata?: { user_type?: string } } | null>(null);
12	    const [onboardingChecked, setOnboardingChecked] = useState(false);
13	    const [onboardingRedirect, setOnboardingRedirect] = useState<string | null>(null);
14	    const [tosAccepted, setTosAccepted] = useState<boolean | null>(null);
15	    const [detectedRole, setDetectedRole] = useState<'worker' | 'company'>('worker');
16	    const [roleRedirect, setRoleRedirect] = useState<string | null>(null);
17	    const location = useLocation();
18	    const { addToast } = useToast();
19	
20	    useEffect(() => {
21	        const checkAuth = async () => {
22	            const { data: { session } } = await supabase.auth.getSession();
23	            const currentUser = session?.user ?? null;
24	            setUser(currentUser as { id: string; user_metadata?: { user_type?: string } } | null);
25	            setLoading(false);
26	
27	            if (currentUser) {
28	                await checkOnboarding(currentUser);
29	                await checkTos(currentUser);
30	            }
31	        };
32	
33	        const checkOnboarding = async (authUser: { id: string; user_metadata?: { user_type?: string } }) => {
34	            const pathname = location.pathname;
35	
36	            if (pathname === '/worker/onboarding' || pathname === '/company/onboarding') {
37	                setOnboardingChecked(true);
38	                return;
39	            }
40	
41	            const userType = authUser.user_metadata?.user_type;
42	
43	            try {
44	                let data = null;
45	                if (userType === 'work') {
46	                    const result = await supabase
47	                        .from('workers')
48	                        .select('onboarding_completed')
49	                        .eq('id', authUser.id)
50	                        .single();
51	                    data = result.data;
52	                } else if (userType === 'hire') {
53	                    const result = await supabase
54	                        .from('companies')
55	                        .select('onboarding_completed')
56	                        .eq('id', authUser.id)
57	                        .single();
58	                    data = result.data;
59	                }
60	
61	                if (data?.onboarding_completed !== true) {
62	                    setOnboardingRedirect(
63	                        userType === 'work' ? '/worker/onboarding' : '/company/onboarding'
64	                    );
65	                }
66	            } catch (error) {
67	                logError('Erro ao verificar onboarding', error);
68	                if (userType === 'work') {
69	                    setOnboardingRedirect('/worker/onboarding');
70	                } else if (userType === 'hire') {
71	                    setOnboardingRedirect('/company/onboarding');
72	                }
73	            }
74	
75	            setOnboardingChecked(true);
76	        };
77	
78	        const checkTos = async (authUser: { id: string; user_metadata?: { user_type?: string } }) => {
79	            const userType = authUser.user_metadata?.user_type;
80

80	
81	            // Tenta workers primeiro
82	            if (userType === 'work') {
83	                const { data: workerData } = await supabase
84	                    .from('workers')
85	                    .select('accepted_tos')
86	                    .eq('id', authUser.id)
87	                    .single();
88	
89	                if (workerData) {
90	                    setTosAccepted(workerData.accepted_tos === true);
91	                    setDetectedRole('worker');
92	                    return;
93	                }
94	            }
95	
96	            // Tenta companies
97	            if (userType === 'hire') {
98	                const { data: companyData } = await supabase
99	                    .from('companies')
100	                    .select('accepted_tos')
101	                    .eq('id', authUser.id)
102	                    .single();
103	
104	                if (companyData) {
105	                    setTosAccepted(companyData.accepted_tos === true);
106	                    setDetectedRole('company');
107	                    return;
108	                }
109	            }
110	
111	            // Usuário sem perfil ainda (em onboarding) — não exibir gate de TOS
112	            setTosAccepted(true);
113	        };
114	
115	        checkAuth();
116	
117	        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
118	            setUser(session?.user as { id: string; user_metadata?: { user_type?: string } } | null);
119	            if (!session?.user) {
120	                setTosAccepted(null);
121	            }
122	            setLoading(false);
123	        });
124	
125	        return () => subscription.unsubscribe();
126	    // eslint-disable-next-line react-hooks/exhaustive-deps
127	    }, []);
128	
129	    if (loading || (user && !onboardingChecked) || (user && tosAccepted === null)) {
130	        return (
131	            <div className="flex h-screen w-full items-center justify-center bg-gray-50">
132	                <Loader2 className="animate-spin text-primary" size={48} />
133	            </div>
134	        );
135	    }
136	
137	    if (!user) return <Navigate to="/" replace />;
138	
139	    // Redirect to onboarding if not completed, but only if not already on the onboarding page
140	    if (onboardingRedirect && location.pathname !== onboardingRedirect) {
141	        return <Navigate to={onboardingRedirect} replace />;
142	    }
143	
144	    // Role isolation: prevent wrong role from accessing wrong routes
145	    if (user && !roleRedirect) {
146	        const userType = user.user_metadata?.user_type;
147	        const pathname = location.pathname;
148	        const workerOnlyPaths = ['/dashboard', '/jobs', '/my-jobs', '/wallet', '/messages', '/profile', '/notifications'];
149	
150	        if (userType === 'work' && pathname.startsWith('/company/')) {
151	            addToast('Você não tem permissão para acessar esta página.', 'error');
152	            setRoleRedirect('/dashboard');
153	        } else if (userType === 'hire' && workerOnlyPaths.some(p => pathname === p || pathname.startsWith(p + '/'))) {
154	            addToast('Você não tem permissão para acessar esta página.', 'error');
155	            setRoleRedirect('/company/dashboard');
156	        }
157	    }
158	
159	    if (roleRedirect) return <Navigate to={roleRedirect} replace />;
160	
161	    // Pular gate de TOS durante onboarding para nao confundir o usuario
162	    const isOnboardingRoute = location.pathname.includes('/onboarding');
163	
164	    if (tosAccepted === false && !isOnboardingRoute) return (
165	        <>
166	            <TosGateModal userRole={detectedRole} onAccepted={() => setTosAccepted(true)} />
167	            <Outlet />
168	        </>
169	    );
170	
171	    return <Outlet />;
172	}
