93	 * 'declined' — freela recusou; NEUTRO, zero punição (R7).
94	 * Demais status: fluxo pull legado.
95	 */
96	export type ApplicationStatus =
97	  | 'pending'
98	  | 'reviewing'
99	  | 'interview'
100	  | 'hired'

100	  | 'hired'
101	  | 'in_progress'
102	  | 'completed'
103	  | 'rejected'
