124	  company_checkout_confirmed_at?: string | null;
125	  // --- campos de convite push (nullable — null = fluxo pull) ---
126	  /** Quando a empresa criou o convite. NULL = aplicação pull. */
127	  invited_by_company_at?: string | null;
128	  /** Quando o freela respondeu ao convite. */
