175	   * Resolve um token de link de convite → retorna o `company_id`.
176	   * Retorna null se o token for inválido ou malformado.
177	   */
178	  resolveInviteToken(token: string): string | null {
179	    try {
180	      const padded = token.replace(/-/g, '+').replace(/_/g, '/');
181	      const payload = atob(padded);
182	      const [companyId] = payload.split(':');
183	      if (!companyId || companyId.length < 30) return null;
184	      return companyId;
